const allItems = $input.all();

// 1. 행 데이터 배열 추출 함수
function getRow(item) { return item?.json?.row || []; }

const r0 = getRow(allItems[0]); // 첫 번째 행: 날짜
const r1 = getRow(allItems[1]); // 두 번째 행: 요일

// 2. 데이터가 존재하는 날짜 컬럼 인덱스 수집 (C열 = 인덱스 2부터 시작)
const dateCols = [];
for (let i = 2; i < r0.length; i++) {
    if (r0[i] !== null && r0[i] !== undefined && r0[i] !== '') {
        dateCols.push(i);
    }
}

// 3. 엑셀 항목 매핑 (A열 라벨 기준) 및 수수료율(B열) 추출
const MR = {
    ubereats_commission_rate: 0,
    doordash_commission_rate: 0
};
let inAppsFeeSection = false;

for (let rowI = 0; rowI < allItems.length; rowI++) {
    const rowData = getRow(allItems[rowI]);
    const rawVal = rowData[0]; // A열 라벨
    if (!rawVal) continue;

    const lb = String(rawVal).trim().toLowerCase();

    // APPS fee 구역 진입 감지
    if (lb === 'apps fee') {
        inAppsFeeSection = true;
        continue;
    }

    // B열(인덱스 1)에 기재된 수수료율(%) 추출 (예: "23%")
    const colB = String(rowData[1] || '').trim();
    const rateMatch = colB.match(/(\d+)%/);

    // Weekly 병합 셀 항목 매핑 추가
    if (lb.startsWith('weekly total sales')) MR.weekly_total_sales = rowI;
    else if (lb.startsWith('weekly cash total')) MR.weekly_cash_total = rowI;
    else if (lb.startsWith('weekly sales after com')) MR.weekly_sales_after_commission = rowI;

    // 일반 매출 항목 매핑
    else if (lb.startsWith('gross sale')) MR.gross_sale = rowI;
    else if (lb.startsWith('card without tips')) MR.card_without_tips = rowI;
    else if (lb.startsWith('card with tips')) MR.card_with_tips = rowI;
    else if (lb.startsWith('paid out')) MR.paid_out = rowI;
    else if (lb.startsWith('cash sale')) MR.cash_sale_incl_gross = rowI;

    // 배달앱 섹션 분리 (매출 vs 수수료)
    else if (lb.startsWith('ubereats')) {
        if (inAppsFeeSection) {
            MR.ubereats_commission = rowI;
            if (rateMatch) MR.ubereats_commission_rate = parseInt(rateMatch[1], 10) / 100;
        } else {
            MR.ubereats = rowI;
        }
    }
    else if (lb.startsWith('doordash')) {
        if (inAppsFeeSection) {
            MR.doordash_commission = rowI;
            if (rateMatch) MR.doordash_commission_rate = parseInt(rateMatch[1], 10) / 100;
        } else {
            MR.doordash = rowI;
        }
    }

    // 기타 합계 항목 매핑
    else if (lb.startsWith('cash and carry')) MR.cash_and_carry = rowI;
    else if (lb.startsWith('total sale') && !lb.includes('after')) MR.total_sale = rowI;
    else if (lb.startsWith('cash expenses')) MR.cash_expenses = rowI;
    else if (lb.startsWith('cash left')) MR.cash_left = rowI;
    else if (lb.startsWith('actual cash')) MR.actual_cash = rowI;
    else if (lb.startsWith('total cash')) MR.total_cash = rowI;
    else if (lb.startsWith('balance')) MR.balance = rowI;
    else if (lb.startsWith('total comissions') || lb.startsWith('total commissions')) MR.total_commissions = rowI;
    else if (lb.startsWith('total sale after comiss') || lb.startsWith('total sale after commiss')) MR.total_sale_after_commission = rowI;
}

// 4. 값 추출 및 숫자 변환 헬퍼
function v(ix, ci) {
    if (ix === undefined) return 0;
    const val = getRow(allItems[ix])[ci];
    if (val === null || val === undefined || val === '') return 0;
    if (typeof val === 'number') return val;

    const n = parseFloat(String(val).replace(/[$,\s]/g, ''));
    return isNaN(n) ? 0 : n;
}

// Weekly 병합 셀(Merged Cell) 유지를 위한 상태 변수
let cur_weekly_total = 0;
let cur_weekly_cash = 0;
let cur_weekly_after_com = 0;

// 5. 최종 JSON 배열 조립 (총 25개 컬럼)
return dateCols.map(ci => {
    // 엑셀 날짜 일련번호 변환
    const excelDate = r0[ci];
    const dateStr = typeof excelDate === 'number' 
        ? new Date(Date.UTC(1899, 11, 30) + excelDate * 86400000).toISOString().split('T')[0]
        : String(excelDate).trim();

    // 병합 셀 Fill-Forward 처리 (새로운 값이 있으면 업데이트, 빈칸이면 이전 값 유지)
    if (MR.weekly_total_sales !== undefined) {
        const raw = getRow(allItems[MR.weekly_total_sales])[ci];
        if (raw !== null && raw !== undefined && raw !== '') cur_weekly_total = v(MR.weekly_total_sales, ci);
    }
    if (MR.weekly_cash_total !== undefined) {
        const raw = getRow(allItems[MR.weekly_cash_total])[ci];
        if (raw !== null && raw !== undefined && raw !== '') cur_weekly_cash = v(MR.weekly_cash_total, ci);
    }
    if (MR.weekly_sales_after_commission !== undefined) {
        const raw = getRow(allItems[MR.weekly_sales_after_commission])[ci];
        if (raw !== null && raw !== undefined && raw !== '') cur_weekly_after_com = v(MR.weekly_sales_after_commission, ci);
    }

    return {
        json: {
            sale_date: dateStr,
            day_of_week: String(r1[ci] || '').trim(),
            gross_sale: v(MR.gross_sale, ci),
            card_without_tips: v(MR.card_without_tips, ci),
            paid_out: v(MR.paid_out, ci),
            card_with_tips: v(MR.card_with_tips, ci),
            cash_sale_incl_gross: v(MR.cash_sale_incl_gross, ci),
            ubereats: v(MR.ubereats, ci),
            doordash: v(MR.doordash, ci),
            cash_and_carry: v(MR.cash_and_carry, ci),
            total_sale: v(MR.total_sale, ci),
            cash_expenses: v(MR.cash_expenses, ci),
            cash_left: v(MR.cash_left, ci),
            actual_cash: v(MR.actual_cash, ci),
            total_cash: v(MR.total_cash, ci),
            balance: v(MR.balance, ci),
            ubereats_commission_rate: MR.ubereats_commission_rate,
            ubereats_commission: v(MR.ubereats_commission, ci),
            doordash_commission_rate: MR.doordash_commission_rate,
            doordash_commission: v(MR.doordash_commission, ci),
            total_commissions: v(MR.total_commissions, ci),
            total_sale_after_commission: v(MR.total_sale_after_commission, ci),
            // 추가된 Weekly 항목 3개
            weekly_total_sales: cur_weekly_total,
            weekly_cash_total: cur_weekly_cash,
            weekly_sales_after_commission: cur_weekly_after_com
        }
    };
});

